  @SuppressWarnings("unchecked") Map<String,InputQuality.Repair> plans=(Map<String,InputQuality.Repair>)get("repairPlans");plans.put("repair:0",plan);shown(new String[][]{state[0],new String[]{"repair:0","其他词","qi ta ci"}},1);require(accept().isEmpty()&&NativeCore.draft(session)[0].equals("shshenme")&&NativeCore.snapshot(session)[0][1].isEmpty(),"reused repair ID cannot commit a different text/reading");checks++;
