  type("nihao");require(NativeCore.moveCursor(session,-1),"26-key cursor accepts bounded left");NativeCore.key(session,'x');require(NativeCore.draft(session)[0].equals("nihaxo"),"typing edits at Rime caret rather than moving candidate selection");checks++;
  NativeCore.mode(session,true,true);for(char key:"64426".toCharArray())NativeCore.key(session,key);require(!NativeCore.moveCursor(session,-1)&&NativeCore.draft(session)[0].equals("64426"),"nine-key locked composition protected from unsupported caret API");checks++;
